def min_seconds_to_leave_opened(n, pos, l, r):
    # Calculate the distance to the nearest boundary (either l or r)
    dist_to_l = abs(pos - l)
    dist_to_r = abs(pos - r)

    # Determine the optimal strategy
    if pos < l:
        return dist_to_l * 2
    elif pos > r:
        return dist_to_r * 2
    else:
        return min(dist_to_l * 2, dist_to_r * 2)

